@@ -0,0 +1,30 @@
+import { slugify } from '../lib/text.js';
+import { formatDate } from '../lib/date.js';
+
+function cardTitle(title) {
+  const trimmed = typeof title === 'string' ? title.trim() : '';
+  if (!trimmed) {
+    throw new TypeError('Event title is required');
+  }
+  return trimmed;
+}
+
+function cardDate(startsAt) {
+  if (typeof startsAt !== 'string' && typeof startsAt !== 'number' && !(startsAt instanceof Date)) {
+    throw new TypeError('Invalid event date');
+  }
+  return formatDate(startsAt);
+}
+
+export function createEventCard(event) {
+  if (event === null || typeof event !== 'object') {
+    throw new TypeError('Event must be an object');
+  }
+  const title = cardTitle(event.title);
+  const dateLabel = cardDate(event.startsAt);
+  const id = slugify(title);
+  if (!id) {
+    throw new TypeError('Event title must contain letters or digits');
+  }
+  return { id, title, dateLabel };
+}

