@@ -0,0 +1,14 @@
+import { createEventCard } from './event-card.js';
+
+export function sortedEventEntries(events) {
+  if (!Array.isArray(events)) {
+    throw new TypeError('Events must be an array');
+  }
+  return events
+    .map((event) => ({ event, card: createEventCard(event), time: new Date(event.startsAt).getTime() }))
+    .sort((a, b) => a.time - b.time);
+}
+
+export function buildAgenda(events) {
+  return sortedEventEntries(events).map((entry) => entry.card);
+}

