@@ -0,0 +1,17 @@
+import { normalizeEmail } from '../lib/validation.js';
+import { retry } from '../lib/retry.js';
+import { buildOrganizerDigest } from './digest.js';
+
+export const DIGEST_ATTEMPTS = 3;
+
+export async function deliverDigest(events, signupsByEvent, organizer, send) {
+  const to = normalizeEmail(organizer?.email);
+  const digest = buildOrganizerDigest(events, signupsByEvent);
+  const payload = {
+    to,
+    subject: 'Event digest',
+    eventIds: digest.map((entry) => entry.id),
+    totalConfirmed: digest.reduce((sum, entry) => sum + entry.confirmed, 0),
+  };
+  return retry(() => send(payload), DIGEST_ATTEMPTS);
+}

